.volume-slider::-webkit-slider-thumb:hover { transform: scale(1.1); box-shadow: rgba(59, 130, 246, 0.4) 0px 4px 12px; }
.volume-slider:focus { outline-offset: 2px; outline: rgba(59, 130, 246, 0.3) solid 2px; }
.volume-slider.muted::-webkit-slider-thumb { border-color: rgb(239, 68, 68); }
.volume-slider.muted::-webkit-slider-thumb:hover { box-shadow: rgba(239, 68, 68, 0.4) 0px 4px 12px; }
.volume-slider.muted:focus { outline-color: rgba(239, 68, 68, 0.3); }

